  "<td>" & tC_卸受注完了 & "</td>" &
  "<td>" & tC_受注残 & "</td>" &
  "<td>" & tC_達成率表示 & "</td>" &
  "<td>" & tC_専売 & "</td>" &
  "<td>" & tC_併売 & "</td>" &
  "<td>" & tC_テレマ & "</td>" &
  "<td>" & tC_完工 & "</td>" &
  "<td>" & tC_最終予測 & "</td>" &
  "<td>" & tC_中間予測 & "</td>" &
  "<td>" & tC_総受注 & "</td>" &
