        "<td>" & GetAsText ( _当月目標 ) & "</td>" &
        "<td>" & GetAsText ( _実績 ) & "</td>" &
        "<td>" & GetAsText ( _卸受注完了 ) & "</td>" &
        "<td>" & GetAsText ( _受注残 ) & "</td>" &
        "<td>" & GetAsText ( _達成率 ) & "</td>" &
        "<td>" & GetAsText ( _専売 ) & "</td>" &
        "<td>" & GetAsText ( _併売 ) & "</td>" &
