  ym_num  = Case ( IsEmpty ( selYM_text ) ; selYM_num ; GetAsNumber ( selYM_text ) ) ;

  sql_text =
  "SELECT \"前月繰越\",\"当月目標\",\"実績\",\"卸受注完了\",\"受注残\",
          \"達成率\",
