Let ( [

/* ===== 共通：選択年月（テキスト／数値 両対応） ===== */
selYM_text = GetAsText ( 計画進捗::年月_g ) ;
selYM_num  = GetAsNumber ( selYM_text ) ;

/* ===== まとめ取得 ===== */
colSep = Char ( 9 ) ;  // フィールド区切り（タブ）
rowSep = "¶" ;         // レコード区切り（段落）

sql = "
SELECT
  \"繰越件数\",
  \"当月受注件数\",
  \"卸注文件数\",
  \"合計件数\",
  \"取次完了件数\",
  \"吉田委託目標\",
  \"吉田繰越\",
  \"吉田受注\",
  \"吉田完工\",
  \"吉田受注差異\",
  \"吉田完工差異\"
FROM \"計画進捗\"
WHERE \"年月\" = ? OR \"年月\" = ?
" ;

res = ExecuteSQL ( sql ; colSep ; rowSep ; selYM_text ; selYM_num ) ;

// 先頭行を取り出し、タブ→段落に置換して GetValue で列参照しやすくする
cols = Case (
  IsEmpty ( res ) or res = "?" ;
  "" ;
  Substitute ( GetValue ( res ; 1 ) ; colSep ; "¶" )
) ;

// ==== 各フィールド値（空なら ""）
vKorikoshi   = GetValue ( cols ; 1 ) ;
vTougetsu    = GetValue ( cols ; 2 ) ;
vOroshi      = GetValue ( cols ; 3 ) ;
vGokei       = GetValue ( cols ; 4 ) ;
vToritsugi   = GetValue ( cols ; 5 ) ;

vItaku       = GetValue ( cols ; 6 ) ;
vY_korikoshi = GetValue ( cols ; 7 ) ;
vY_juchu     = GetValue ( cols ; 8 ) ;
vY_kanko     = GetValue ( cols ; 9 ) ;
vY_sa_juchu  = GetValue ( cols ; 10 ) ;
vY_sa_kanko  = GetValue ( cols ; 11 ) ;

/* ====== 数値整形＆クラス ====== */

/* 左ブロックの「件」表記 */
sKorikoshi = If ( IsEmpty ( vKorikoshi ) ; "" ; GetAsText ( vKorikoshi ) & "件" ) ;
sTougetsu  = If ( IsEmpty ( vTougetsu  ) ; "" ; GetAsText ( vTougetsu  ) & "件" ) ;
sOroshi    = If ( IsEmpty ( vOroshi    ) ; "" ; GetAsText ( vOroshi    ) & "件" ) ;
sGokei     = If ( IsEmpty ( vGokei     ) ; "" ; GetAsText ( vGokei     ) & "件" ) ;
sToritsugi = If ( IsEmpty ( vToritsugi ) ; "" ; GetAsText ( vToritsugi ) & "件" ) ;

/* 右ブロックの数値 */
nItaku    = GetAsNumber ( vItaku ) ;
nYkrk     = GetAsNumber ( vY_korikoshi ) ;
nYjuchu   = GetAsNumber ( vY_juchu ) ;
nYkanko   = GetAsNumber ( vY_kanko ) ;
nSaJuchu  = GetAsNumber ( vY_sa_juchu ) ;
nSaKanko  = GetAsNumber ( vY_sa_kanko ) ;
nSoujuchu = nYkrk + nYjuchu ;

clsJ = Case ( nSaJuchu < 0 ; "neg" ; "" ) ;
clsK = Case ( nSaKanko < 0 ; "neg" ; "" ) ;

/* ===== HTML/CSS（総受注のみホバー無効化） ===== */
html = "
<!doctype html><html lang='ja'><head><meta charset='utf-8'>
<meta name='viewport' content='width=device-width,initial-scale=1'>
<title>受注サマリー</title>
<style>
  :root{ --line:#333; --head:#f5f5f5; --hover:#fff8cc; --blue:#133e79; --neg:#c1121f; }
  *{box-sizing:border-box; margin:0; padding:0}
  html,body{ width:100%; height:100%; font-family:-apple-system,BlinkMacSystemFont,'Yu Gothic UI','Yu Gothic',Meiryo,Arial,sans-serif; background:#fff; color:#111; }
  .wrap{ display:grid; grid-template-columns: 1fr 1fr; gap:20px; width:100%; height:100%; }
  .card{ border:1px solid var(--line); padding:10px; }
  .title{ font-weight:700; font-size:14px; margin-bottom:6px; }
  table{ border-collapse:collapse; width:100%; font-size:13px; }
  th,td{ border:1px solid var(--line); padding:4px 8px; text-align:right; white-space:nowrap; }
  th{ background:var(--head); text-align:center; font-weight:700; }
  /* ← ここを限定指定に変更。nohover クラスのテーブルはホバーしない */
  table:not(.nohover) tr:hover td{ background:var(--hover); }
  .neg{ color:var(--neg); font-weight:700; }
  .highlight{ background:var(--blue); color:#fff; font-weight:700; }
</style>
</head>
<body>
  <div class='wrap'>

    <!-- 左ブロック -->
    <section class='card'>
      <p class='title'>処理件数</p>
      <table>
        <thead>
          <tr>
            <th>繰越件数</th>
            <th>当月受注</th>
            <th>卸注文</th>
            <th>合計件数</th>
            <th>取次完了</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>" & sKorikoshi & "</td>
            <td>" & sTougetsu  & "</td>
            <td>" & sOroshi    & "</td>
            <td>" & sGokei     & "</td>
            <td>" & sToritsugi & "</td>
          </tr>
        </tbody>
      </table>
    </section>

    <!-- 右ブロック -->
    <section class='card'>
      <p class='title'>吉田</p>
      <table>
        <thead>
          <tr>
            <th>委託目標</th>
            <th>繰越</th>
            <th>受注</th>
            <th>完工</th>
            <th>受注差異</th>
            <th>完工差異</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>" & GetAsText ( Round ( nItaku   ; 0 ) ) & "</td>
            <td>" & GetAsText ( Round ( nYkrk    ; 0 ) ) & "</td>
            <td>" & GetAsText ( Round ( nYjuchu  ; 0 ) ) & "</td>
            <td>" & GetAsText ( Round ( nYkanko  ; 0 ) ) & "</td>
            <td class='" & clsJ & "'>" & GetAsText ( Round ( nSaJuchu ; 0 ) ) & "</td>
            <td class='" & clsK & "'>" & GetAsText ( Round ( nSaKanko ; 0 ) ) & "</td>
          </tr>
        </tbody>
      </table>

      <!-- 総受注テーブルだけ hover 無効 -->
      <table class='nohover' style='margin-top:8px'>
        <tbody>
          <tr>
            <td style='text-align:left'>総受注</td>
            <td class='highlight' style='text-align:right'>" & GetAsText ( Round ( nSoujuchu ; 0 ) ) & "</td>
          </tr>
        </tbody>
      </table>
    </section>

  </div>
</body></html>
" ;

b64 = Base64EncodeRFC ( 4648 ; TextEncode ( html ; "utf-8" ; 1 ) )

] ;

"data:text/html;base64," & b64
)

